function height(keys, fanout){ var h=1, cap=fanout; while(cap<keys){ cap*=fanout; h++; } return h; }
var keys=[1000,1000000,1000000000];
for(var i=0;i<keys.length;i++){ console.log(keys[i]+" keys, fanout 500 -> height "+height(keys[i],500)); }
console.log("Fanout 500 keeps a billion keys at height 4: 4 I/Os per lookup.");

